package javax.microedition.lcdui;
public class Form extends Screen {
 private final java.util.Vector items=new java.util.Vector();public Form(String title){setTitle(title);}public Form(String title,Item[] data){this(title);for(Item i:data)append(i);}public int append(Item item){if(item==null)throw new NullPointerException();items.addElement(item);return items.size()-1;}public int append(String s){return append(new StringItem(null,s));}public int append(Image image){return append(new ImageItem(null,image,ImageItem.LAYOUT_DEFAULT,null));}public Item get(int i){return (Item)items.elementAt(i);}public int size(){return items.size();}public void delete(int i){items.removeElementAt(i);}public void deleteAll(){items.removeAllElements();}public void set(int i,Item item){items.setElementAt(item,i);}public void insert(int i,Item item){items.insertElementAt(item,i);}protected void paint(Graphics g){g.setColor(0x132437);g.fillRect(0,0,getWidth(),getHeight());g.setColor(0xffffff);g.drawString(getTitle()==null?"Java":getTitle(),8,8,20);int y=30;for(int i=0;i<items.size();i++){Item item=(Item)items.elementAt(i);item.render(g,8,y,getWidth()-16);y+=item.height();}}
}
